save(218,dict(paragraphs=["Zakir Khan writes Odia poetry and fiction alongside work in journalism and translation. His contributions to Samata and Sahitya Charcha establish that literary range, while an Odisha government library-selection record lists his Nandan Kaanan, published by Pakshighara Prakashanee. His writing here often asks how language can respond to the pressures of social and economic life.","Eka Arthanaitika Kabita, dedicated to Kishan Pattnayak, asks whether a poem can serve ordinary people, farmers and forest communities. Gote Gapara Plot turns a father's ambition for his son into a painful story of material success and solitude. Elsewhere, Manisha imagines an overturned natural world to question territorial division, Bata makes the road itself a philosophical companion, and Kabitatiera Apekhare waits for poetry to return to a blank sheet carried in a pocket."],sources=[source('Samata — Swapna, by Zakir Khan','https://thesamata.in/swapna-a-poem-by-zakir-khan','Odia poem with author note identifying poet, translator and journalist.','search_index_full_poem_and_bio; direct open failed'),source('Sahitya Charcha — Ba-ba-ba','https://www.sahityacharcha.com/2021/01/22/ba-ba-ba/','Odia fiction publication under Zakir Khan byline.'),source('Odisha Culture Department — RRRLF selected books 2010–11','https://culture.odisha.gov.in/sites/default/files/2022-06/List%20of%20Selected%20Books%20Under%20Raja%20Rammohan%20Ray%20Library%20Foundation%20%28RRRLF%29%20Scheme%20for%20the%20Year%202010-11.pdf','Entry331: Nandan Kaanan, Zakir Khan, Pakshighara Prakashanee,2006, Odia.','search_index_pdf_catalogue_row')],books=[dict(title='Nandan Kaanan',detail='Pakshighara Prakashanee, 2006; official library-selection catalogue, entry 331.',url='https://culture.odisha.gov.in/sites/default/files/2022-06/List%20of%20Selected%20Books%20Under%20Raja%20Rammohan%20Ray%20Library%20Foundation%20%28RRRLF%29%20Scheme%20for%20the%20Year%202010-11.pdf')],identity_match='Odia byline, fiction/poetry output and journalist role match captured writer; excluded Hindi comedian and other namesakes.',poems_read=[dict(id=i,title=t,coverage='Complete original Odia poem',basis=b) for i,t,b in [(202,'ଏକ ଅର୍ଥନୈତିକ କବିତା','Kishan Pattnayak dedication; meaning/money, ordinary people, farmers, forests and resistance to corporate greed.'),(754,'ଗୋଟେ ଗପର ପ୍ଲଟ୍','Software-engineer son abroad, remittances/ATM, bereaved father and old-age-home enquiry.'),(577,'ମଣିଷ','Exchanged sky/sea, fish as stars, divided earth and human suspension.'),(707,'ବାଟ','Path as fragment of infinity and exchange between traveller and road.'),(457,'କବିତାଟିଏର ଅପେକ୍ଷାରେ','Lost unity with poetry, blank paper in pocket and anticipated return.')]],limitations=['Specific current OTV employment not independently confirmed; retained only in captured biography.','Official catalogue supports book attribution, not a full bibliography or current availability.'],search_queries=['"Zakir Khan" Odia poet OTV','"ଜାକିର ଖାନ" କବି','"Zakir Khan" odia books -comedian -comedy -Indore'],next_action='Author/editor to confirm preferred Roman spelling, current professional note and wider bibliography.'))
